@pytest.fixture
def db_factory():
    engine = create_engine(
        "sqlite:///:memory:", connect_args={"check_same_thread": False}, poolclass=StaticPool
    )
    Base.metadata.create_all(engine)
    return sessionmaker(bind=engine, expire_on_commit=False)


@pytest.fixture
def admin_client(db_factory):
    """Overrides get_current_admin_user with a stub whose AdminProfile.role is
    mutable per-test via `set_role` -- mirrors test_be6_router.py's fixture."""

    def _override_get_db():
        db = db_factory()
        try:
            yield db
        finally:
            db.close()

    stub_user = make_admin_stub(
        db_factory, role=AdminRole.RM, firebase_uid="uid-be1-router-test", email="admin@example.com"
    )

    app.dependency_overrides[get_db] = _override_get_db
    app.dependency_overrides[get_settings] = lambda: Settings(firebase_auth_disabled=True)
    app.dependency_overrides[get_current_admin_user] = lambda: stub_user

    def _set_role(role: AdminRole):
        db = db_factory()
        db.query(AdminProfile).filter_by(user_id=stub_user.id).update({"role": role})
        db.commit()
        db.close()
        # BE-2: admin_profile is loaded eagerly on stub_user (make_admin_stub) -- keep
        # the cached relationship in sync with the row this function just changed.
        stub_user.admin_profile.role = role

    try:
        yield TestClient(app), stub_user, _set_role
    finally:
        app.dependency_overrides.clear()


# --- Positive: each route reaches its service method, returns the pinned DTO ---------


def test_rm_submit_allotment_reaches_service_and_returns_201(admin_client, monkeypatch):
    http, stub_user, _set_role = admin_client
    captured: dict = {}

    def _fake_submit_allotment(self, req):
        captured["req"] = req
        return _stub_dto(kind="allotment", status="pending")

    monkeypatch.setattr(OnboardingService, "submit_allotment", _fake_submit_allotment, raising=False)

    body = {
        "client_id": str(uuid.uuid4()),
        "model_id": str(uuid.uuid4()),
        "multiplier": "2",
        "expected_cash_in": None,
    }
    resp = http.post("/api/rm/allotment", json=body)
    assert resp.status_code == 201, resp.text
    assert resp.json()["kind"] == "allotment"
    assert "req" in captured
    assert captured["req"].multiplier == Decimal("2")


